function fareCombinations(coins, amount) {
  const MOD = 1000000007;
  const count = (i, remaining) => {
    if (remaining === 0) return 1;
    if (i === coins.length) return 0;
    let total = 0;
    for (let k = 0; k * coins[i] <= remaining; k++) total = (total + count(i + 1, remaining - k * coins[i])) % MOD;
    return total;
  };
  return count(0, amount);
}

function fareCombinations(coins, amount) {
  const MOD = 1000000007;
  const ways = new Array(amount + 1).fill(0);
  ways[0] = 1;
  for (const coin of coins)
    for (let t = coin; t <= amount; t++) ways[t] = (ways[t] + ways[t - coin]) % MOD;
  return ways[amount];
}
